-- Issue #307 (Kindle party membership and human primaries): party membership (one party per citizen) and the primary election, voter receipt and anonymous ranked-ballot tables, separate from the civic_* presidential tables. The ballot table carries no timestamp and no citizen. Additive tables only.
CREATE TABLE IF NOT EXISTS party_members ( clerk_user_id TEXT COLLATE "C" PRIMARY KEY REFERENCES citizens(clerk_user_id), party_id TEXT COLLATE "C" NOT NULL CHECK(party_id IN ('steady-hand','open-ledger','dockside-builders')), joined_at BIGINT NOT NULL );
CREATE TABLE IF NOT EXISTS primary_elections ( id TEXT COLLATE "C" PRIMARY KEY, nation_id TEXT COLLATE "C" NOT NULL CHECK(nation_id='kindle'), policy TEXT COLLATE "C" NOT NULL CHECK(policy IN ('tier1-human-v1','preview-citizen-v1')), opens_at BIGINT NOT NULL, closes_at BIGINT NOT NULL, closed_at BIGINT, result_json TEXT COLLATE "C", CHECK(closes_at=opens_at+259200), CHECK(closed_at IS NULL OR closed_at>=closes_at), CHECK(result_json IS NULL OR closed_at IS NOT NULL) );
CREATE TABLE IF NOT EXISTS primary_voter_receipts ( election_id TEXT COLLATE "C" NOT NULL REFERENCES primary_elections(id), clerk_user_id TEXT COLLATE "C" NOT NULL REFERENCES citizens(clerk_user_id), party_id TEXT COLLATE "C" NOT NULL CHECK(party_id IN ('steady-hand','open-ledger','dockside-builders')), request_id TEXT COLLATE "C" NOT NULL UNIQUE, checked_at BIGINT NOT NULL, ballot_written BIGINT NOT NULL DEFAULT 0 CHECK(ballot_written IN (0,1)), policy TEXT COLLATE "C" NOT NULL CHECK(policy IN ('tier1-human-v1','preview-citizen-v1')), PRIMARY KEY(election_id,clerk_user_id) );
CREATE TABLE IF NOT EXISTS primary_anonymous_ballots ( id TEXT COLLATE "C" PRIMARY KEY, election_id TEXT COLLATE "C" NOT NULL REFERENCES primary_elections(id), party_id TEXT COLLATE "C" NOT NULL CHECK(party_id IN ('steady-hand','open-ledger','dockside-builders')), ranking TEXT COLLATE "C" NOT NULL, policy TEXT COLLATE "C" NOT NULL CHECK(policy IN ('tier1-human-v1','preview-citizen-v1')) );
CREATE INDEX IF NOT EXISTS idx_primary_ballots_election ON primary_anonymous_ballots(election_id);
